package com.xinhe.nexus.management.controller;
import com.xinhe.nexus.common.api.ApiResponse;import com.xinhe.nexus.management.auth.*;import com.xinhe.nexus.management.service.ErpReturnService;import com.xinhe.nexus.management.service.ErpReturnService.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/erp") public class ErpReturnController{private final ErpReturnService service;public ErpReturnController(ErpReturnService service){this.service=service;}@GetMapping("/sales-returns")public ApiResponse<List<Map<String,Object>>> list(@RequestAttribute(AuthConstants.CURRENT_USER_ATTRIBUTE)ManagementUser u,@RequestParam(required=false)String returnNo,@RequestParam(required=false)String orderNo,@RequestParam(required=false)String status){return ApiResponse.success(service.returns(u,returnNo,orderNo,status));}@GetMapping("/sales-returns/{id}")public ApiResponse<Map<String,Object>> detail(@RequestAttribute(AuthConstants.CURRENT_USER_ATTRIBUTE)ManagementUser u,@PathVariable long id){return ApiResponse.success(service.detail(u,id));}@PostMapping("/sales-returns")public ApiResponse<Map<String,Object>> create(@RequestAttribute(AuthConstants.CURRENT_USER_ATTRIBUTE)ManagementUser u,@RequestBody ReturnInput body){return ApiResponse.success(service.create(u,body));}@PostMapping("/sales-returns/{id}/approve")public ApiResponse<Void> approve(@RequestAttribute(AuthConstants.CURRENT_USER_ATTRIBUTE)ManagementUser u,@PathVariable long id,@RequestBody Decision body){service.decide(u,id,true,body.opinion());return ApiResponse.success(null);}@PostMapping("/sales-returns/{id}/reject")public ApiResponse<Void> reject(@RequestAttribute(AuthConstants.CURRENT_USER_ATTRIBUTE)ManagementUser u,@PathVariable long id,@RequestBody Decision body){service.decide(u,id,false,body.opinion());return ApiResponse.success(null);}@PostMapping("/sales-returns/{id}/receive")public ApiResponse<Void> receive(@RequestAttribute(AuthConstants.CURRENT_USER_ATTRIBUTE)ManagementUser u,@PathVariable long id){service.receive(u,id);return ApiResponse.success(null);}@GetMapping("/sales-reports")public ApiResponse<List<Map<String,Object>>> report(@RequestAttribute(AuthConstants.CURRENT_USER_ATTRIBUTE)ManagementUser u,@RequestParam(defaultValue="customer")String dimension){return ApiResponse.success(service.report(u,dimension));}}
